/*
    India districts, cities, and pins. Inserts only rows that are not already there.
    Does not insert Other. Run M00_UserAddressLocation_Other.sql after this.
    State names: Orissa is stored as Odisha. Dadra and Daman are stored under
    Dadra and Nagar Haveli and Daman and Diu.
*/
SET NOCOUNT ON;
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
IF OBJECT_ID(N'tempdb..#IndiaLoad') IS NOT NULL DROP TABLE #IndiaLoad;
CREATE TABLE #IndiaLoad
(
    StateName nvarchar(100) NOT NULL,
    DistrictName nvarchar(100) NOT NULL,
    CityName nvarchar(100) NOT NULL,
    PinCode nvarchar(10) NOT NULL
);













































































































































































































































SELECT DISTINCT l.DistrictName, s.StateId, N'Tufan Powar', '2026-10-02', 0
FROM #IndiaLoad l
JOIN dbo.StateMaster s ON s.StateName = l.StateName AND ISNULL(s.DeleteStatus, 0) = 0
JOIN dbo.CountryMaster c ON c.CountryId = s.CountryId AND c.CountryName = N'India' AND ISNULL(c.DeleteStatus, 0) = 0
WHERE NOT EXISTS (
    SELECT 1 FROM dbo.DistrictMaster d
    WHERE d.StateId = s.StateId AND d.DistrictName = l.DistrictName AND ISNULL(d.DeleteStatus, 0) = 0
);

SELECT DISTINCT l.CityName, d.DistrictId, N'Tufan Powar', '2026-10-02', 0
FROM #IndiaLoad l
JOIN dbo.StateMaster s ON s.StateName = l.StateName AND ISNULL(s.DeleteStatus, 0) = 0
JOIN dbo.CountryMaster c ON c.CountryId = s.CountryId AND c.CountryName = N'India' AND ISNULL(c.DeleteStatus, 0) = 0
JOIN dbo.DistrictMaster d ON d.StateId = s.StateId AND d.DistrictName = l.DistrictName AND ISNULL(d.DeleteStatus, 0) = 0
WHERE NOT EXISTS (
    SELECT 1 FROM dbo.CityMaster city
    WHERE city.DistrictId = d.DistrictId AND city.CityName = l.CityName AND ISNULL(city.DeleteStatus, 0) = 0
);

SELECT DISTINCT l.PinCode, city.CityId, N'Tufan Powar', '2026-10-02', 0
FROM #IndiaLoad l
JOIN dbo.StateMaster s ON s.StateName = l.StateName AND ISNULL(s.DeleteStatus, 0) = 0
JOIN dbo.CountryMaster c ON c.CountryId = s.CountryId AND c.CountryName = N'India' AND ISNULL(c.DeleteStatus, 0) = 0
JOIN dbo.DistrictMaster d ON d.StateId = s.StateId AND d.DistrictName = l.DistrictName AND ISNULL(d.DeleteStatus, 0) = 0
JOIN dbo.CityMaster city ON city.DistrictId = d.DistrictId AND city.CityName = l.CityName AND ISNULL(city.DeleteStatus, 0) = 0
WHERE NOT EXISTS (
    SELECT 1 FROM dbo.PinCodeMaster p
    WHERE p.CityId = city.CityId AND p.PinCode = l.PinCode AND ISNULL(p.DeleteStatus, 0) = 0
);
DROP TABLE #IndiaLoad;
